import struct
from dnsbuild import name

def cs(b):
    if isinstance(b,str): b=b.encode()
    return bytes([len(b)])+b

TY = dict(A=1,NS=2,CNAME=5,SOA=6,PTR=12,HINFO=13,MX=15,TXT=16,AAAA=28,LOC=29,
          SRV=33,NAPTR=35,OPT=41,SSHFP=44,TLSA=52,OPENPGPKEY=61,EUI48=108,EUI64=109,
          URI=256,CAA=257)

def A(a=(1,2,3,4)): return bytes(a)
def AAAA(h='20010db8000000000000000000000001'): return bytes.fromhex(h)
def NS(n='ns1.example.net'): return name(n)
def CNAME(n='alias.example.net'): return name(n)
def PTR(n='ptr.example.net'): return name(n)
def SOA(mname='ns.example.net', rname='hostmaster.example.net', serial=2020010101, refresh=3600, retry=600, expire=1209600, minimum=60):
    return name(mname)+name(rname)+struct.pack('!IIIII', serial, refresh, retry, expire, minimum)
def HINFO(cpu='Intel', os='Linux'): return cs(cpu)+cs(os)
def MX(pref=10, ex='mail.example.net'): return struct.pack('!H',pref)+name(ex)
def TXT(*parts):
    if not parts: parts=(b'hello world',)
    return b''.join(cs(p) for p in parts)
def LOC(ver=0, size=0x12, hp=0x16, vp=0x13, lat=0x8b0d2118, lon=0x7f3a5b18, alt=0x00989680):
    return bytes([ver,size,hp,vp])+struct.pack('!III',lat,lon,alt)
def SRV(pri=1, wt=2, port=8080, tgt='service.example.net'):
    return struct.pack('!HHH',pri,wt,port)+name(tgt)
def NAPTR(order=100, pref=10, flags='S', svc='SIP+D2U', regexp='!^.*$!sip:info@example.net!', repl='.'):
    return struct.pack('!HH',order,pref)+cs(flags)+cs(svc)+cs(regexp)+name(repl)
def SSHFP(alg=1, ft=1, fp=bytes(range(20))): return bytes([alg,ft])+fp
def TLSA(usage=3, sel=1, mt=1, data=bytes(range(32))): return bytes([usage,sel,mt])+data
def OPENPGPKEY(k=b'\xca\xfe\xba\xbe'): return k
def EUI48(b=bytes([0xab,0xcd,0xef,0x12,0x34,0x56])): return b
def EUI64(b=bytes([0xab,0xcd,0xef,0x12,0x34,0x56,0x78,0x9a])): return b
def URI(pri=10, wt=1, tgt=b'https://example.net/'): return struct.pack('!HH',pri,wt)+tgt
def CAA(flags=0, tag=b'issue', val=b'letsencrypt.org'): return bytes([flags])+bytes([len(tag)])+tag+val
EOF
